  #tasksService = inject(TasksService)

  tasks = injectQuery(() => this.#tasksService.allTasks())
  clearMutation = injectMutation(() => this.#tasksService.addTask())
  addMutation = injectMutation(() => this.#tasksService.addTask())

  newItem = ''
