@Injectable({
  providedIn: 'root',
})
export class AutocompleteService {
  readonly #http = inject(HttpClient)

  getSuggestions = (term: string = '') =>
    term.trim() === ''
      ? of({ suggestions: [] })
      : this.#http.get<Response>(
          `/api/autocomplete?term=${encodeURIComponent(term)}`,
        )
}

