  await delay(70)
  if (failNextMutation) {
    failNextMutation = false
    throw new Error('Forced mutation failure (test)')
  }

  const nextTodo: Todo = {
    id: nextTodoId,
    title,
  }

  nextTodoId += 1
  todos = [...todos, nextTodo]

  return { ...nextTodo }
}

