    strictPort: true,
  },
})

const DEFAULT_SSR_HOST = '127.0.0.1'
const DEFAULT_SSR_PORT = 4174

function normalizeUrlHost(host) {
  if (host.includes(':') && !host.startsWith('[') && !host.endsWith(']')) {
    return `[${host}]`
  }

  return host
}

function resolvePort(name, fallback) {
  const value = process.env[name]
  if (!value) {
    return fallback
  }

  const parsedPort = Number.parseInt(value, 10)
  const isValidPort =
    Number.isInteger(parsedPort) && parsedPort > 0 && parsedPort <= 65_535

  if (!isValidPort) {
    throw new Error(
      `Invalid ${name} "${value}". Expected an integer between 1 and 65535.`,
    )
  }

  return parsedPort
}

export const SSR_PORT = resolvePort('SSR_PORT', DEFAULT_SSR_PORT)
export const SSR_HOST = process.env.SSR_HOST ?? DEFAULT_SSR_HOST

function resolveConnectHost(host) {
  if (host === '0.0.0.0') {
    return '127.0.0.1'
  }

  if (host === '::') {
    return '[::1]'
  }

  return normalizeUrlHost(host)
}

function resolvePublicOrigin(host, port) {
  const explicitOrigin = process.env.SSR_PUBLIC_ORIGIN
  if (explicitOrigin) {
    const url = new URL(explicitOrigin)
    return url.origin
  }

  const explicitPublicHost = process.env.SSR_PUBLIC_HOST
  const publicHost = explicitPublicHost
    ? normalizeUrlHost(explicitPublicHost)
    : resolveConnectHost(host)

  return `http://${publicHost}:${port}`
}

export const SSR_CONNECT_HOST = resolveConnectHost(SSR_HOST)
export const SSR_BASE_URL = `http://${SSR_CONNECT_HOST}:${SSR_PORT}`
export const SSR_PUBLIC_ORIGIN = resolvePublicOrigin(SSR_HOST, SSR_PORT)

import type { CreateQueryOptions } from '@tanstack/lit-query'

export const DATA_QUERY_KEY = ['ssr-example-data'] as const
export const DEFAULT_MESSAGE = 'Hello from SSR!'
export const QUERY_STALE_TIME = 30_000

export type DataResponse = {
  message: string
  requestCount: number
  servedAt: string
}

function resolveApiUrl(pathname: string, apiBaseUrl: string): string {
  if (!apiBaseUrl) {
    return pathname
  }

  return new URL(pathname, apiBaseUrl).toString()
}

async function readJson<TResponse>(response: Response): Promise<TResponse> {
  let payload: TResponse | { error?: string } | null = null

  try {
    payload = (await response.json()) as TResponse | { error?: string }
  } catch {
    if (response.ok) {
      throw new Error(
        `Failed to parse JSON response with status ${response.status}.`,
      )
    }
  }

  if (!response.ok) {
    const errorDetail =
      payload &&
      typeof payload === 'object' &&
      'error' in payload &&
      typeof payload.error === 'string'
        ? `: ${payload.error}`
        : ''

    throw new Error(
      `Request failed with status ${response.status}${errorDetail}`,
    )
  }

  return payload as TResponse
}

export function createDataQueryOptions(apiBaseUrl = '') {
  return {
    queryKey: DATA_QUERY_KEY,
    queryFn: async ({ signal }) => {
      const response = await fetch(resolveApiUrl('/api/data', apiBaseUrl), {
        signal,
      })
      return readJson<DataResponse>(response)
    },
    retry: false,
    staleTime: QUERY_STALE_TIME,
  } satisfies CreateQueryOptions<
    DataResponse,
    Error,
    DataResponse,
    DataResponse,
    typeof DATA_QUERY_KEY
  >
}

