export default (req: NextApiRequest, res: NextApiResponse) => {
  const cursor = parseInt(req.query.cursor) || 0
  const pageSize = 4

  const data = Array(pageSize)
    .fill(0)
    .map((_, i) => {
      return {
        name: 'Project ' + (i + cursor) + ` (server time: ${Date.now()})`,
