import { useEffect } from 'react'
import { AppState } from 'react-native'
import type { AppStateStatus } from 'react-native'

export function useAppState(onChange: (status: AppStateStatus) => void) {
  useEffect(() => {
    const subscription = AppState.addEventListener('change', onChange)
    return () => {
      subscription.remove()
    }
  }, [onChange])
}

import * as React from 'react'
import NetInfo from '@react-native-community/netinfo'
import { onlineManager } from '@tanstack/react-query'
import { Platform } from 'react-native'

export function useOnlineManager() {
  React.useEffect(() => {
    // React Query already supports on reconnect auto refetch in web browser
    if (Platform.OS !== 'web') {
      return NetInfo.addEventListener((state) => {
        onlineManager.setOnline(
          state.isConnected != null &&
            state.isConnected &&
            Boolean(state.isInternetReachable),
        )
      })
    }
  }, [])
}

import * as React from 'react'

export function useRefreshByUser(refetch: () => Promise<unknown>) {
  const [isRefetchingByUser, setIsRefetchingByUser] = React.useState(false)

  async function refetchByUser() {
    setIsRefetchingByUser(true)

    try {
      await refetch()
    } finally {
      setIsRefetchingByUser(false)
    }
  }

  return {
    isRefetchingByUser,
    refetchByUser,
  }
}

import * as React from 'react'
import { useFocusEffect } from '@react-navigation/native'

export function useRefreshOnFocus(refetch: () => void) {
  const enabledRef = React.useRef(false)

  useFocusEffect(
    React.useCallback(() => {
      if (enabledRef.current) {
        refetch()
      } else {
        enabledRef.current = true
      }
    }, [refetch]),
  )
}

import movies from '../data/movies.json'

export type Movie = {
  title: string
  year: number
}

export type MovieDetails = Movie & {
  info: {
    plot: string
    actors: string[]
  }
}

function delay(t: number) {
  return new Promise(function (resolve) {
    setTimeout(resolve, t)
  })
}

export async function fetchMovies(): Promise<Movie[]> {
  console.log('fetchMovies')

  await delay(200 + Math.floor(Math.random() * 2000))

  return Promise.resolve(
    movies
      .slice(0, 100)
      .map((movie) => ({ title: movie.title, year: movie.year })),
  )
}

export async function fetchMovie(title: string): Promise<MovieDetails> {
  console.log('fetchMovie', title)

  await delay(200 + Math.floor(Math.random() * 2000))

  const result = movies.filter((item) => item.title === title)

  if (result.length === 0) {
    throw new Error('Movie not found')
  }
  return Promise.resolve(result[0] as MovieDetails)
}

