]

// Serializing a selection for the clipboard is a userland concern: the table
// hands back `getSelectedCellRangesData()` as raw values, and the delimiter,
// the null representation, and the quoting rules are all yours to pick. This is
// the spreadsheet-flavored version.
function escapeTsvValue(value: unknown) {
  const text = value == null ? '' : String(value)
  const safeText =
    typeof value === 'string' && /^[\t\r ]*[=+@-]/.test(value)
      ? `'${text}`
      : text

  // spreadsheets expect a field to be quoted once it contains a delimiter, a
  // newline, or a quote, with inner quotes doubled
  return /["\t\n\r]/.test(safeText)
    ? `"${safeText.replace(/"/g, '""')}"`
    : safeText
}

function toTsv(ranges: Array<Array<Array<unknown>>>) {
  return ranges
    .map((grid) =>
      grid.map((row) => row.map(escapeTsvValue).join('\t')).join('\n'),
    )
    .join('\n\n') // blank line between final selected regions
}

Alpine.data('table', () => {
  const local = Alpine.reactive({ data: makeData(20) })

  const table = createTable(
    {
      features,
      columns,
      get data() {
        return local.data
      },
      getRowId: (row: Person) => row.id,
      enableCellSelection: true, // enable cell selection for all cells
      // initialState: { cellSelection: [] }, // select cells on first render
      // atoms: { cellSelection: cellSelectionAtom }, // own selection state with an external atom
      // state: { cellSelection }, // classic controlled state; pair with onCellSelectionChange
      // onCellSelectionChange: setCellSelection,
      // enableCellRangeSelection: false, // disable Shift-click and drag ranges; default true
      // enableMultiCellRangeSelection: false, // allow only one rectangle at a time; default true
      // enableCellSelectionDrag: false, // disable drag-to-select; default true
      // isCellRangeSelectionEvent: event => Boolean(event.metaKey), // use Meta instead of Shift
      debugTable: true,
    },
    // Alpine re-renders from a version counter, and the selector decides which
    // slices bump it. cellSelection has to be here or the highlight never moves.
    (state) => ({
      cellSelection: state.cellSelection,
      sorting: state.sorting,
      columnOrder: state.columnOrder,
      columnPinning: state.columnPinning,
      columnVisibility: state.columnVisibility,
    }),
  )

  // optionally, reset the cellSelection state not only when data changes, but
  // also when column order, pinning, visibility, or sorting changes
  // customize this to your needs
  let isFirstColumnLayout = true
  let lastLayoutKey = ''

  const resetOnLayoutChange = () => {
    const layoutKey = JSON.stringify([
      table.atoms.columnOrder.get(),
      table.atoms.columnPinning.get(),
      table.atoms.columnVisibility.get(),
      table.atoms.sorting.get(),
    ])

    if (isFirstColumnLayout) {
      isFirstColumnLayout = false
      lastLayoutKey = layoutKey
      return
    }

    if (layoutKey !== lastLayoutKey) {
      lastLayoutKey = layoutKey
      queueMicrotask(() => table.resetCellSelection(true))
    }
  }

  const copySelection = () =>
    void navigator.clipboard.writeText(toTsv(table.getSelectedCellRangesData()))

  return {
    table,
    FlexRender,

    refreshData() {
      local.data = makeData(20)
    },
    stressTest() {
      local.data = makeData(1_000)
    },

    // Alpine cannot call chained methods cleanly from directives, so the
    // per-cell reads and handlers are exposed here.
    cellClass(cell: Cell<typeof features, Person>) {
      // Most cells in a large grid are unselected, so bail before asking for
      // edges. getSelectionEdges() would otherwise resolve the cell's position
      // a second time just to discover it is not selected.
      if (!cell.getIsSelected()) {
        return cell.getIsFocused()
          ? 'cell-selectable cell-focused'
          : 'cell-selectable'
      }

      const edges = cell.getSelectionEdges()

      return [
        'cell-selectable',
        'cell-selected',
        cell.getIsFocused() && 'cell-focused',
        edges.top && 'cell-edge-top',
        edges.right && 'cell-edge-right',
        edges.bottom && 'cell-edge-bottom',
        edges.left && 'cell-edge-left',
      ]
        .filter(Boolean)
        .join(' ')
    },
    onCellMouseDown(cell: Cell<typeof features, Person>, event: MouseEvent) {
      cell.getSelectionStartHandler()(event)
    },
    onCellMouseEnter(cell: Cell<typeof features, Person>, event: MouseEvent) {
      cell.getSelectionExtendHandler()(event)
    },
    sortIndicator(header: Header<typeof features, Person, unknown>) {
      const sorted = header.column.getIsSorted()
      return sorted === 'asc' ? ' 🔼' : sorted === 'desc' ? ' 🔽' : ''
    },

    selectionSummary() {
      resetOnLayoutChange()
      return `${table.getSelectedCellCount().toLocaleString()} cells selected across ${table
        .getCellSelectionRowIds()
        .length.toLocaleString()} rows and ${
        table.getCellSelectionColumnIds().length
      } columns`
    },

    shuffleColumns() {
      table.setColumnOrder(
        faker.helpers.shuffle(table.getAllLeafColumns().map((d) => d.id)),
      )
    },
    reverseColumns() {
      table.setColumnOrder(
        [...table.getAllLeafColumns().map((column) => column.id)].reverse(),
      )
    },

    copySelection,

    logRangesData() {
      console.info(
        'table.getSelectedCellRangesData()',
        table.getSelectedCellRangesData(),
      )
    },

    stringifiedState() {
      return local.data.length < 1_001
        ? JSON.stringify(table.store.get(), null, 2)
        : ''
    },

    // keyboard navigation is TanStack Hotkeys driving the table's imperative
    // APIs; table-core ships no keydown handling of its own. Alpine has no
    // hotkeys adapter, so the framework-agnostic core handler is used directly.
    onGridKeyDown: createMultiHotkeyHandler({
      ArrowUp: () => table.moveCellSelection('up'),
      ArrowDown: () => table.moveCellSelection('down'),
      ArrowLeft: () => table.moveCellSelection('left'),
      ArrowRight: () => table.moveCellSelection('right'),
      'Shift+ArrowUp': () => table.extendCellSelection('up'),
      'Shift+ArrowDown': () => table.extendCellSelection('down'),
      'Shift+ArrowLeft': () => table.extendCellSelection('left'),
      'Shift+ArrowRight': () => table.extendCellSelection('right'),
      'Mod+A': () => table.selectAllCells(),
      Escape: () => table.resetCellSelection(true),
      'Mod+C': () => copySelection(),
    }),
  }
})

window.Alpine = Alpine
Alpine.start()

import { faker } from '@faker-js/faker'

// twice the usual example's field count, so there are enough columns to
// meaningfully hide, reorder, and pin while a cell selection is active
export type Person = {
  id: string
  firstName: string
  lastName: string
  age: number
  visits: number
  progress: number
  status: 'relationship' | 'complicated' | 'single'
  email: string
  phone: string
  city: string
  country: string
  department: string
  salary: number
  subRows?: Array<Person>
}

const range = (len: number) => {
  const arr: Array<number> = []
  for (let i = 0; i < len; i++) {
    arr.push(i)
  }
  return arr
}

const newPerson = (): Person => {
  return {
    id: faker.string.uuid(),
    firstName: faker.person.firstName(),
    lastName: faker.person.lastName(),
    age: faker.number.int(40),
    visits: faker.number.int(1000),
    progress: faker.number.int(100),
    status: faker.helpers.shuffle<Person['status']>([
      'relationship',
      'complicated',
      'single',
    ])[0],
    email: faker.internet.email(),
    phone: faker.phone.number(),
    city: faker.location.city(),
    country: faker.location.country(),
    department: faker.commerce.department(),
    salary: faker.number.int({ min: 40_000, max: 200_000 }),
  }
}

export function makeData(...lens: Array<number>) {
  const makeDataLevel = (depth = 0): Array<Person> => {
    const len = lens[depth]
    return range(len).map((_d): Person => {
      return {
        ...newPerson(),
        subRows: lens[depth + 1] ? makeDataLevel(depth + 1) : undefined,
      }
    })
  }

  return makeDataLevel()
}

import { expect, test } from '@playwright/test'
import type { Locator, Page } from '@playwright/test'
import path from 'node:path'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  try {
    await page.route(
      'https://unpkg.com/react-scan/dist/auto.global.js',
      (route) =>
        route.fulfill({
          contentType: 'application/javascript',
          body: '',
        }),
    )
    await page.goto(server.url)
    return { errors, server }
  } catch (error) {
    await server.close()
    throw error
  }
}

function getTable(page: Page) {
  return page
    .locator('table:visible, .divTable:visible')
    .filter({ has: page.locator('thead th, .thead .th') })
    .filter({ has: page.locator('tbody tr, .tbody .tr') })
    .first()
}

function getHeaderCells(table: Locator) {
  return table.locator('thead th, .thead .th')
}

function getBodyRows(table: Locator) {
  return table.locator('tbody tr, .tbody .tr')
}

async function getFirstBodyRowData(table: Locator) {
  const row = getBodyRows(table).first()
  const firstInput = row
    .locator('input:not([type="checkbox"]):not([type="radio"])')
    .first()

  if ((await firstInput.count()) > 0 && (await firstInput.isVisible())) {
    return firstInput.inputValue()
  }

  const text = await row.textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const table = getTable(page)
    const bodyRows = getBodyRows(table)

    await expect(table).toBeVisible()
    await expect(getHeaderCells(table).first()).toBeVisible()
    await expect(bodyRows.first()).toBeVisible()

    const regenerateButton = page
      .getByRole('button', { name: /^Regenerate Data$/i })
      .first()

    if ((await regenerateButton.count()) > 0) {
      await expect(regenerateButton).toBeVisible()

      const firstRowBefore = await getFirstBodyRowData(table)

      await regenerateButton.click()

      await expect
        .poll(() => getFirstBodyRowData(table))
        .not.toBe(firstRowBefore)
      await expect(bodyRows.first()).toBeVisible()
    }

    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('selects an inclusive cell range with Shift-click', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const rows = getBodyRows(getTable(page))
    await expect(rows.first()).toBeVisible()

    await rows.nth(0).locator('td').nth(0).click()
    await rows
      .nth(2)
      .locator('td')
      .nth(2)
      .click({ modifiers: ['Shift'] })

    await expect(page.locator('td.cell-selected')).toHaveCount(9)
    await expect(rows.nth(0).locator('td').nth(0)).toHaveClass(/cell-focused/)
    await expect(rows.nth(3).locator('td').nth(0)).not.toHaveClass(
      /cell-selected/,
    )
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

import Alpine from 'alpinejs'
import {
  FlexRender,
  cellSelectionFeature,
  cellSpanningFeature,
  columnFilteringFeature,
  columnVisibilityFeature,
  createColumnHelper,
  createFilteredRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  createTable,
  filterFn_includesString,
  rowPaginationFeature,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_basic,
  tableFeatures,
} from '@tanstack/alpine-table'
import { makeData, makeSummaryData } from './makeData'
import './index.css'
import type { Cell, Header } from '@tanstack/alpine-table'
import type { Shift, SummaryRow } from './makeData'

const features = tableFeatures({
  cellSelectionFeature,
  cellSpanningFeature,
  columnFilteringFeature,
  columnVisibilityFeature,
  rowPaginationFeature,
  rowSortingFeature,
  filteredRowModel: createFilteredRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  sortedRowModel: createSortedRowModel(),
  filterFns: { includesString: filterFn_includesString },
  sortFns: { alphanumeric: sortFn_alphanumeric, basic: sortFn_basic },
})

const columnHelper = createColumnHelper<typeof features, Shift>()

const columns = columnHelper.columns([
  columnHelper.accessor('region', {
    header: 'Region',
    sortFn: 'alphanumeric',
    // Adjacent rows that share a region merge into one vertically spanning
    // cell. Spans always derive from the rows that are actually rendered, so
    // sorting, filtering, and paging just change which rows are adjacent.
    spanRows: true,
  }),
  columnHelper.accessor('team', {
    header: 'Team',
    sortFn: 'alphanumeric',
    spanRows: true,
  }),
  columnHelper.accessor('shift', {
    header: 'Shift',
    sortFn: 'alphanumeric',
    // The predicate form: shifts only merge while the table is sorted by the
    // shift column, so the predicate itself is visibly reactive.
    spanRows: ({ column, value, anchorValue }) =>
      column.getIsSorted() !== false && value === anchorValue,
  }),
  columnHelper.accessor('employee', {
    header: 'Employee',
    sortFn: 'alphanumeric',
    filterFn: 'includesString',
  }),
  columnHelper.accessor('hours', {
    header: 'Hours',
    sortFn: 'basic',
  }),
  columnHelper.accessor('status', {
    header: 'Status',
    sortFn: 'alphanumeric',
    filterFn: 'includesString',
  }),
])

const summaryFeatures = tableFeatures({
  cellSpanningFeature,
  columnVisibilityFeature,
})

const summaryColumnHelper = createColumnHelper<
  typeof summaryFeatures,
  SummaryRow
>()

const summaryColumns = summaryColumnHelper.columns([
  summaryColumnHelper.accessor('label', {
    header: 'Shift',
    // Subtotal rows render one label cell covering every column but the
    // total. `Infinity` clamps to the rest of the cell's pinned region.
    spanColumns: ({ row }) => (row.original.kind === 'subtotal' ? Infinity : 1),
  }),
  summaryColumnHelper.accessor('region', {
    header: 'Region',
  }),
  summaryColumnHelper.accessor('hours', {
    header: 'Hours',
  }),
])

/** The structural slice a cell needs to expose for the span-skip filter. */
type SpannableCell = {
  id: string
  getRowSpan: () => number
  getColSpan: () => number
}

Alpine.data('table', () => {
  const local = Alpine.reactive({
    data: makeData(),
    summaryData: makeSummaryData(),
    spanningEnabled: true,
  })

  const table = createTable(
    {
      debugTable: true,
      features,
      columns,
      get data() {
        return local.data
      },
      // Option getters are the Alpine idiom for reactive options: the memoized
      // span index lists `enableCellSpanning` in its deps, so flipping the
      // reactive flag both invalidates the index and re-evaluates the bindings
      // that read it.
      get enableCellSpanning() {
        return local.spanningEnabled
      },
      initialState: {
        pagination: { pageIndex: 0, pageSize: 12 },
      },
    },
    (state) => state, // default selector
  )

  const summaryTable = createTable(
    {
      debugTable: true,
      features: summaryFeatures,
      columns: summaryColumns,
      get data() {
        return local.summaryData
      },
    },
    (state) => state, // default selector
  )

  return {
    table,
    summaryTable,
    FlexRender,

    refreshData() {
      local.data = makeData()
    },

    get spanningEnabled() {
      return local.spanningEnabled
    },
    setSpanningEnabled(enabled: boolean) {
      local.spanningEnabled = enabled
    },

    /**
     * A span of 0 means this cell is covered by a cell above or to its left.
     * Skip it. Do NOT render `rowspan="0"`: in HTML that means "span to the
     * end of the row group", so forgetting this check merges the cell down the
     * whole tbody instead of rendering nothing. Alpine templates cannot skip
     * an `x-for` item inline, so the filter lives here.
     */
    spanCells(row: { getVisibleCells: () => Array<SpannableCell> }) {
      return row
        .getVisibleCells()
        .filter((cell) => cell.getRowSpan() !== 0 && cell.getColSpan() !== 0)
    },

    /**
     * Selection styling for the spanning table. A merged cell is always
     * entirely selected or entirely unselected: the selection bounds expand to
     * enclose any merge they touch, so the tint and the outline land on the
     * rendered anchor.
     */
    cellClass(cell: Cell<typeof features, Shift>) {
      const base =
        cell.getRowSpan() > 1 ? 'cell-selectable span-cell' : 'cell-selectable'

      if (!cell.getIsSelected()) {
        return cell.getIsFocused() ? `${base} cell-focused` : base
      }

      const edges = cell.getSelectionEdges()

      return [
        base,
        'cell-selected',
        cell.getIsFocused() && 'cell-focused',
        edges.top && 'cell-edge-top',
        edges.right && 'cell-edge-right',
        edges.bottom && 'cell-edge-bottom',
        edges.left && 'cell-edge-left',
      ]
        .filter(Boolean)
        .join(' ')
    },

    // Alpine cannot call chained methods cleanly from directives, so the
    // per-cell handlers are exposed here.
    onCellMouseDown(cell: Cell<typeof features, Shift>, event: MouseEvent) {
      cell.getSelectionStartHandler()(event)
    },
    onCellMouseEnter(cell: Cell<typeof features, Shift>, event: MouseEvent) {
      cell.getSelectionExtendHandler()(event)
    },

    sortIndicator(header: Header<typeof features, Shift, unknown>) {
      const sorted = header.column.getIsSorted()
      return sorted === 'asc' ? ' 🔼' : sorted === 'desc' ? ' 🔽' : ''
    },

    columnLabel(columnId: string) {
      return String(table.getColumn(columnId)!.columnDef.header)
    },

    statusFilterValue() {
      return (
        (table.getColumn('status')!.getFilterValue() as string | undefined) ??
        ''
      )
    },
    setStatusFilter(value: string) {
      table.getColumn('status')!.setFilterValue(value || undefined)
    },

    employeeFilterValue() {
      return (
        (table.getColumn('employee')!.getFilterValue() as string | undefined) ??
        ''
      )
    },
    setEmployeeFilter(value: string) {
      table.getColumn('employee')!.setFilterValue(value || undefined)
    },

    pageLabel() {
      const { pageIndex } = table.store.get().pagination
      return `Page ${pageIndex + 1} of ${table.getPageCount()}`
    },
    pageSize() {
      return table.store.get().pagination.pageSize
    },

    stringifiedState() {
      return JSON.stringify(table.store.get(), null, 2)
    },
  }
})

window.Alpine = Alpine
Alpine.start()

import { faker } from '@faker-js/faker'

export type ShiftStatus = 'Approved' | 'Pending' | 'Rejected'

export type Shift = {
  id: string
  region: 'North' | 'South' | 'East' | 'West'
  team: string
  shift: 'Morning' | 'Evening' | 'Night'
  employee: string
  hours: number
  status: ShiftStatus
}

const REGIONS: Array<Shift['region']> = ['North', 'South', 'East', 'West']
const TEAMS = ['Alpha', 'Bravo', 'Charlie']
const SHIFTS: Array<Shift['shift']> = ['Morning', 'Evening', 'Night']
const STATUSES: Array<ShiftStatus> = ['Approved', 'Pending', 'Rejected']

/**
 * Rows are emitted region-major, then team, then shift, so equal values are
 * already adjacent. Value-based row spanning only merges adjacent rows, so a
 * per-row random generator would produce a table with no merges at all until
 * the user sorted it.
 */
export function makeData(
  regions = REGIONS.length,
  teams = TEAMS.length,
  shifts = SHIFTS.length,
): Array<Shift> {
  const rows: Array<Shift> = []

  for (let r = 0; r < regions; r++) {
    for (let t = 0; t < teams; t++) {
      for (let s = 0; s < shifts; s++) {
        rows.push({
          id: `${r}-${t}-${s}`,
          region: REGIONS[r % REGIONS.length],
          team: TEAMS[t % TEAMS.length],
          shift: SHIFTS[s % SHIFTS.length],
          employee: faker.person.fullName(),
          hours: faker.number.int({ min: 4, max: 12 }),
          status: STATUSES[faker.number.int({ max: 2 })],
        })
      }
    }
  }

  return rows
}

export type SummaryRow = {
  id: string
  kind: 'shift' | 'subtotal'
  label: string
  region: Shift['region'] | ''
  hours: number
}

/**
 * A small fixed dataset for the column-spanning panel: per-region hour
 * subtotals rendered as full-width label rows between the data rows.
 */
export function makeSummaryData(): Array<SummaryRow> {
  const rows: Array<SummaryRow> = []

  for (const region of REGIONS.slice(0, 2)) {
    let total = 0
    for (const team of TEAMS) {
      const hours = faker.number.int({ min: 8, max: 40 })
      total += hours
      rows.push({
        id: `${region}-${team}`,
        kind: 'shift',
        label: `${region} / ${team}`,
        region,
        hours,
      })
    }
    rows.push({
      id: `${region}-subtotal`,
      kind: 'subtotal',
      label: `${region} total`,
      region: '',
      hours: total,
    })
  }

  return rows
}

