  tickCount: number
  updateCount: number
  supersededUpdateCount: number
}

export interface MarketFeedObserver {
  messageReceived?: () => void
  mutationStarted?: () => void
  batchApplied?: (batch: MarketFeedBatch) => void
  renderCommitted?: () => void
}

export interface MarketFeedActions {
  toggle: () => void
  setInstrumentCount: (count: number) => void
  setTargetRate: (rate: number) => void
  setPublishInterval: (intervalMs: number) => void
  setSparklineUpdates: (enabled: boolean) => void
  setSparklineSampleInterval: (intervalMs: number) => void
  runBurst: () => void
  reset: () => void
}

export class MarketFeedController {
  readonly workerReady = createAtom(false)
  readonly running = createAtom(
    !new URLSearchParams(location.search).has('paused'),
  )
  readonly instrumentCount = createAtom(initialMarketFeedConfig.instrumentCount)
  readonly targetTicksPerSecond = createAtom(
    initialMarketFeedConfig.targetSamplesPerSecond,
  )
  readonly publishIntervalMs = createAtom(
    initialMarketFeedConfig.publishIntervalMs,
  )
  readonly updateSparklines = createAtom(
    initialMarketFeedConfig.updateSparklines,
  )
  readonly sparklineSampleIntervalMs = createAtom(
    initialMarketFeedConfig.sparklineSampleIntervalMs,
  )
  readonly quotes = createAtom<Array<MarketQuote>>([])
  readonly actions: MarketFeedActions
  readonly #observers = new Set<MarketFeedObserver>()
  readonly #runtime = {
    worker: null as Worker | null,
    feedSessionId: 0,
    renderPending: false,
    resetWaitingForCommit: false,
    resetSnapshotReady: false,
    quoteIndexBySymbol: new Map<string, number>(),
  }

  constructor() {
    this.actions = {
      toggle: () => {
        const running = !this.running.get()
        this.running.set(running)
        this.#post({ type: 'set-running', running })
      },
      setInstrumentCount: (count) => {
        this.instrumentCount.set(count)
        this.#resetWorker(count)
      },
      setTargetRate: (rate) => {
        const sampleRate = normalizeFeedSampleRate(rate)
        this.targetTicksPerSecond.set(sampleRate)
        this.#post({ type: 'set-rate', ticksPerSecond: sampleRate })
      },
      setPublishInterval: (publishIntervalMs) => {
        this.publishIntervalMs.set(publishIntervalMs)
        this.#post({
          type: 'set-publish-interval',
          intervalMs: publishIntervalMs,
        })
      },
      setSparklineUpdates: (enabled) => {
        this.updateSparklines.set(enabled)
        this.#post({ type: 'set-sparklines', enabled })
      },
      setSparklineSampleInterval: (intervalMs) => {
        this.sparklineSampleIntervalMs.set(intervalMs)
        this.#post({ type: 'set-sparkline-interval', intervalMs })
      },
      runBurst: () => this.#post({ type: 'burst', tickCount: 25_000 }),
      reset: () => this.#resetWorker(this.instrumentCount.get()),
    }
  }

  start(): () => void {
    const worker = new Worker(
      new URL('./worker/market-feed.worker.ts', import.meta.url),
      { type: 'module' },
    )
    this.#runtime.worker = worker
    worker.addEventListener('message', this.#handleWorkerMessage)
    worker.addEventListener('error', this.#handleWorkerError)
    this.#post({
      type: 'start',
      rowCount: this.instrumentCount.get(),
      running: this.running.get(),
      ticksPerSecond: this.targetTicksPerSecond.get(),
      publishIntervalMs: this.publishIntervalMs.get(),
      updateSparklines: this.updateSparklines.get(),
      sparklineSampleIntervalMs: this.sparklineSampleIntervalMs.get(),
    })
    return () => this.stop()
  }

  stop(): void {
    this.#runtime.worker?.removeEventListener(
      'message',
      this.#handleWorkerMessage,
    )
    this.#runtime.worker?.removeEventListener('error', this.#handleWorkerError)
    this.#runtime.worker?.terminate()
    this.#runtime.worker = null
    this.#observers.clear()
  }

  observe(observer: MarketFeedObserver): () => void {
    this.#observers.add(observer)
    return () => this.#observers.delete(observer)
  }

  getQuoteBySymbol(
    quotes: Array<MarketQuote>,
    symbol: string | null,
  ): MarketQuote | null {
    if (symbol === null) return null

    const index = this.#runtime.quoteIndexBySymbol.get(symbol)
    return index === undefined ? null : (quotes[index] ?? null)
  }

  completeRender(): void {
    if (!this.#runtime.renderPending) return

    this.#runtime.renderPending = false
    for (const observer of this.#observers) {
      observer.renderCommitted?.()
    }
    if (
      this.#runtime.resetWaitingForCommit &&
      this.#runtime.resetSnapshotReady
    ) {
      this.#runtime.resetWaitingForCommit = false
      this.#runtime.resetSnapshotReady = false
      this.#post({ type: 'set-running', running: this.running.get() })
    }
  }

  readonly #handleWorkerMessage = ({
    data,
  }: MessageEvent<MarketFeedEvent>): void => {
    if (data.type === 'snapshot') {
      this.#runtime.feedSessionId = data.sessionId
      if (this.#runtime.resetWaitingForCommit) {
        this.#runtime.resetSnapshotReady = true
      }
      this.#startMutation()
      const quotes = hydrateMarketQuotes(data.quotes)
      this.#runtime.quoteIndexBySymbol = new Map(
        quotes.map((quote, index) => [quote.symbol, index]),
      )
      batch(() => {
        this.quotes.set(quotes)
        this.workerReady.set(true)
      })
      return
    }

    if (data.sessionId !== this.#runtime.feedSessionId) return

    for (const observer of this.#observers) {
      observer.messageReceived?.()
    }
    this.#startMutation()
    this.quotes.set(applyMarketUpdates(this.quotes.get(), data.updates))
    const feedBatch = {
      tickCount: data.tickCount,
      updateCount: data.updates.length,
      supersededUpdateCount: data.coalescedUpdateCount,
    }
    for (const observer of this.#observers) {
      observer.batchApplied?.(feedBatch)
    }
  }

  readonly #handleWorkerError = (error: ErrorEvent): void => {
    batch(() => {
      this.workerReady.set(false)
      this.running.set(false)
    })
    console.error('Market feed worker failed', error)
  }

  #resetWorker(rowCount: number): void {
    this.workerReady.set(false)
    if (this.running.get()) {
      this.#runtime.resetWaitingForCommit = true
      this.#runtime.resetSnapshotReady = false
      this.#post({ type: 'set-running', running: false })
    }
    this.#post({ type: 'reset', rowCount })
  }

  #startMutation(): void {
    this.#runtime.renderPending = true
    for (const observer of this.#observers) {
      observer.mutationStarted?.()
    }
  }

  #post(command: MarketFeedCommand): void {
    this.#runtime.worker?.postMessage(command)
  }
}

/**
 * U.S. and international instruments are interleaved so ordinary benchmark
 * sizes exercise multiple symbol formats and market labels.
 */
export const globalInstruments = Object.freeze(
  marketInstruments.flatMap((instrument, index) => {
    const internationalInstrument =
      index % INTERNATIONAL_INSERTION_INTERVAL === 0
        ? internationalInstruments[index / INTERNATIONAL_INSERTION_INTERVAL]
        : undefined

    return internationalInstrument
      ? [instrument, internationalInstrument]
      : [instrument]
  }),
) as unknown as ReadonlyArray<BaseInstrument>

import { globalInstruments } from '../market-instruments.ts'
import type {
  MarketQuoteSnapshot,
  MarketQuoteUpdate,
} from './market-feed-protocol'

const INITIAL_MARKET_SEED = 0x4d41524b
const LIVE_FEED_SEED = 0x5449434b

export class MarketFeedEngine {
  #quotes: Array<MarketQuoteSnapshot> = []
  #lastHistorySampledAt = new Uint32Array(0)
  #random = createRandom(2_026)
  #rowCursor = 0
  #tickIndex = 0

  reset(count: number): Array<MarketQuoteSnapshot> {
    const random = createRandom(INITIAL_MARKET_SEED ^ count)
    const createdAt = Date.now()

    this.#quotes = Array.from({ length: count }, (_, index) => {
      const [baseSymbol, company, market] =
        globalInstruments[index % globalInstruments.length]
      const series = Math.floor(index / globalInstruments.length)
      const symbol = series === 0 ? baseSymbol : `${baseSymbol}${series}`
      const previousClose = roundPrice(20 + random() * 480)
      const open = roundPrice(previousClose * (1 + (random() - 0.5) * 0.016))
      const spread = Math.max(0.01, open * (0.0002 + random() * 0.0004))
      const history = Array.from({ length: 24 }, (_, historyIndex) =>
        roundPrice(
          open *
            (1 + Math.sin(historyIndex / 4) * 0.002 + (random() - 0.5) * 0.001),
        ),
      )
      const volume = Math.floor(50_000 + random() * 2_000_000)
      const lastSize = Math.floor(10 + random() * 5_000)

      return {
        id: `instrument-${index}`,
        symbol,
        company,
        venue: market,
        previousClose,
        open,
        high: open,
        low: open,
        price: open,
        bid: roundPrice(open - spread / 2),
        ask: roundPrice(open + spread / 2),
        bidSize: Math.floor(100 + random() * 25_000),
        askSize: Math.floor(100 + random() * 25_000),
        lastSize,
        lastMove: 0,
        lastUpdatedAt: createdAt,
        volume,
        turnover: roundMoney(open * volume),
        history,
      }
    })

    this.#random = createRandom(LIVE_FEED_SEED ^ count)
    this.#rowCursor = 0
    this.#lastHistorySampledAt = new Uint32Array(count)
    this.#lastHistorySampledAt.fill(createdAt >>> 0)

    return this.#quotes.map((quote) => ({
      ...quote,
      history: [...quote.history],
    }))
  }

  applyTicks(
    tickCount: number,
    updateSparklines: boolean,
    sparklineSampleIntervalMs: number,
  ): Array<MarketQuoteUpdate> {
    if (this.#quotes.length === 0 || tickCount <= 0) return []

    const updatedAt = Date.now()
    const sampledAt = updatedAt >>> 0
    const sampleIntervalMs = Math.max(16, sparklineSampleIntervalMs)
    const updatedQuotes = new Map<number, MarketQuoteUpdate>()
    const stride = 97

    this.#tickIndex = 0
    while (this.#tickIndex < tickCount) {
      this.#rowCursor = (this.#rowCursor + stride) % this.#quotes.length
      const quote = this.#quotes[this.#rowCursor]
      const lastSampledAt = this.#lastHistorySampledAt[this.#rowCursor]
      const shouldUpdateHistory =
        updateSparklines &&
        (sampledAt - lastSampledAt) >>> 0 >= sampleIntervalMs

      if (shouldUpdateHistory) {
        this.#lastHistorySampledAt[this.#rowCursor] = sampledAt
      }

      this.#applyTick(quote, shouldUpdateHistory, updatedAt)

      const previousUpdate = updatedQuotes.get(this.#rowCursor)
      updatedQuotes.set(this.#rowCursor, {
        index: this.#rowCursor,
        price: quote.price,
        bid: quote.bid,
        ask: quote.ask,
        bidSize: quote.bidSize,
        askSize: quote.askSize,
        lastSize: quote.lastSize,
        lastMove: quote.lastMove,
        lastUpdatedAt: quote.lastUpdatedAt,
        high: quote.high,
        low: quote.low,
        volume: quote.volume,
        turnover: quote.turnover,
        ...(shouldUpdateHistory || previousUpdate?.history
          ? { history: [...quote.history] }
          : {}),
      })
      this.#tickIndex++
    }

    return [...updatedQuotes.values()]
  }

  #applyTick(
    quote: MarketQuoteSnapshot,
    updateHistory: boolean,
    updatedAt: number,
  ): void {
    const previousPrice = quote.price
    const volatility = 0.00015 + this.#random() * 0.0012
    const move = previousPrice * (this.#random() - 0.495) * volatility
    const nextPrice = roundPrice(Math.max(0.1, previousPrice + move))
    const spread = Math.max(
      0.01,
      nextPrice * (0.00015 + this.#random() * 0.0005),
    )

    quote.lastMove = nextPrice - previousPrice
    quote.price = nextPrice
    quote.high = Math.max(quote.high, nextPrice)
    quote.low = Math.min(quote.low, nextPrice)
    quote.bid = roundPrice(nextPrice - spread / 2)
    quote.ask = roundPrice(nextPrice + spread / 2)
    quote.bidSize = Math.floor(100 + this.#random() * 25_000)
    quote.askSize = Math.floor(100 + this.#random() * 25_000)
    quote.lastSize = Math.floor(10 + this.#random() * 5_000)
    quote.lastUpdatedAt = updatedAt
    quote.volume += quote.lastSize
    quote.turnover = roundMoney(quote.turnover + nextPrice * quote.lastSize)

    if (updateHistory) {
      quote.history = [...quote.history.slice(-23), nextPrice]
    }
  }
}

function createRandom(seed: number): () => number {
  const runtime = { state: seed >>> 0 }
  return () => {
    runtime.state += 0x6d2b79f5
    const stateValue = runtime.state
    const firstMix = Math.imul(stateValue ^ (stateValue >>> 15), stateValue | 1)
    const secondMix =
      firstMix + Math.imul(firstMix ^ (firstMix >>> 7), firstMix | 61)
    const value = firstMix ^ secondMix
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296
  }
}

function roundPrice(value: number): number {
  return Math.round(value * 100) / 100
}

function roundMoney(value: number): number {
  return Math.round(value * 100) / 100
}

import { initialMarketFeedConfig } from '../market-feed-config'
import { MarketFeedEngine } from './market-feed-engine'
import type {
  MarketFeedCommand,
  MarketFeedEvent,
  MarketQuoteUpdate,
} from './market-feed-protocol'

const engine = new MarketFeedEngine()
const pendingUpdates = new Map<number, MarketQuoteUpdate>()
const runtime = {
  sessionId: 0,
  pendingTickCount: 0,
  pendingCoalescedUpdateCount: 0,
  initialized: false,
  running: true,
  ticksPerSecond: initialMarketFeedConfig.targetSamplesPerSecond,
  publishIntervalMs: initialMarketFeedConfig.publishIntervalMs,
  publishTimerId: null as ReturnType<typeof setInterval> | null,
  updateSparklines: initialMarketFeedConfig.updateSparklines,
  sparklineSampleIntervalMs: initialMarketFeedConfig.sparklineSampleIntervalMs,
  tickBudget: 0,
  lastTickAt: performance.now(),
}

addEventListener('message', ({ data }: MessageEvent<MarketFeedCommand>) => {
  switch (data.type) {
    case 'start':
      runtime.running = data.running
      runtime.ticksPerSecond = data.ticksPerSecond
      runtime.publishIntervalMs = data.publishIntervalMs
      runtime.updateSparklines = data.updateSparklines
      runtime.sparklineSampleIntervalMs = data.sparklineSampleIntervalMs
      restartPublishTimer()
      reset(data.rowCount)
      break
    case 'set-running':
      runtime.running = data.running
      break
    case 'set-rate':
      runtime.ticksPerSecond = data.ticksPerSecond
      break
    case 'set-publish-interval':
      runtime.publishIntervalMs = Math.max(4, data.intervalMs)
      restartPublishTimer()
      break
    case 'set-sparklines':
      runtime.updateSparklines = data.enabled
      break
    case 'set-sparkline-interval':
      runtime.sparklineSampleIntervalMs = Math.max(16, data.intervalMs)
      break
    case 'reset':
      reset(data.rowCount)
      break
    case 'burst':
      produceTicks(data.tickCount)
      flush()
      break
  }
})

setInterval(() => {
  const now = performance.now()
  const elapsed = Math.min(100, Math.max(0, now - runtime.lastTickAt))
  runtime.lastTickAt = now

  if (runtime.initialized && runtime.running) {
    runtime.tickBudget += (runtime.ticksPerSecond * elapsed) / 1_000
    const tickCount = Math.floor(runtime.tickBudget)
    runtime.tickBudget -= tickCount
    produceTicks(tickCount)
  }
}, 16)

restartPublishTimer()

function reset(rowCount: number): void {
  runtime.initialized = true
  runtime.sessionId++
  runtime.pendingTickCount = 0
  runtime.pendingCoalescedUpdateCount = 0
  pendingUpdates.clear()
  runtime.tickBudget = 0
  runtime.lastTickAt = performance.now()

  post({
    type: 'snapshot',
    sessionId: runtime.sessionId,
    quotes: engine.reset(rowCount),
  })
}

function produceTicks(tickCount: number): void {
  if (!runtime.initialized || tickCount <= 0) return

  runtime.pendingTickCount += tickCount
  for (const update of engine.applyTicks(
    tickCount,
    runtime.updateSparklines,
    runtime.sparklineSampleIntervalMs,
  )) {
    const previousUpdate = pendingUpdates.get(update.index)
    if (previousUpdate) runtime.pendingCoalescedUpdateCount++
    pendingUpdates.set(update.index, {
      ...update,
      ...(update.history || !previousUpdate?.history
        ? {}
        : { history: previousUpdate.history }),
    })
  }
}

function flush(): void {
  if (runtime.pendingTickCount === 0) return

  const message: MarketFeedEvent = {
    type: 'updates',
    sessionId: runtime.sessionId,
    tickCount: runtime.pendingTickCount,
    coalescedUpdateCount: runtime.pendingCoalescedUpdateCount,
    updates: [...pendingUpdates.values()],
  }

  runtime.pendingTickCount = 0
  runtime.pendingCoalescedUpdateCount = 0
  pendingUpdates.clear()
  post(message)
}

function restartPublishTimer(): void {
  if (runtime.publishTimerId !== null) {
    clearInterval(runtime.publishTimerId)
  }
  runtime.publishTimerId = setInterval(
    flush,
    Math.max(4, runtime.publishIntervalMs),
  )
}

function post(event: MarketFeedEvent): void {
  postMessage(event)
}

