import { HttpClient, HttpParams } from '@angular/common/http'
import {
  ChangeDetectionStrategy,
  Component,
  inject,
  linkedSignal,
  signal,
} from '@angular/core'
import { ReactiveFormsModule } from '@angular/forms'
import {
  FlexRender,
  columnFilteringFeature,
  createColumnHelper,
  globalFilteringFeature,
  injectTable,
  rowPaginationFeature,
  rowSortingFeature,
  tableFeatures,
} from '@tanstack/angular-table'
import { map } from 'rxjs'
import { rxResource } from '@angular/core/rxjs-interop'
import type {
  ColumnDef,
  PaginationState,
  SortingState,
} from '@tanstack/angular-table'
import type { WritableSignal } from '@angular/core'

export type Todo = {
  userId: number
  id: number
  title: string
  completed: boolean
}

const features = tableFeatures({
  rowPaginationFeature,
  columnFilteringFeature,
  globalFilteringFeature,
  rowSortingFeature,
})

const columnHelper = createColumnHelper<typeof features, Todo>()

type TodoResponse = { items: Array<Todo>; totalCount: number }

@Component({
  selector: 'app-root',
  imports: [FlexRender, ReactiveFormsModule],
  templateUrl: './app.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class App {
  readonly client = inject(HttpClient)
  readonly pagination = signal<PaginationState>({
    pageSize: 10,
    pageIndex: 0,
  })

  readonly sorting = signal<SortingState>([{ id: 'id', desc: false }])
  readonly globalFilter = signal<string | null>(null)
  readonly data = rxResource({
    params: () => ({
      page: this.pagination(),
      globalFilter: this.globalFilter(),
      sorting: this.sorting(),
    }),
    stream: ({ params: { page, globalFilter, sorting } }) => {
      let httpParams = new HttpParams({
        fromObject: {
          _page: page.pageIndex + 1,
          _limit: page.pageSize,
        },
      })
      if (globalFilter) {
        httpParams = httpParams.set('title_like', globalFilter)
      }
      if (sorting.length) {
        const keys: Array<string> = []
        const orders: Array<string> = []
        for (const sort of sorting) {
          keys.push(sort.id)
          orders.push(sort.desc ? 'desc' : 'asc')
        }
        httpParams = httpParams
          .set('_sort', keys.join(','))
          .set('_order', orders.join(','))
      }

      return this.client
        .get<Array<Todo>>(`https://jsonplaceholder.typicode.com/todos`, {
          params: httpParams,
          observe: 'response',
        })
        .pipe(
          map((response) => {
            return {
              items: response.body ?? [],
              totalCount: Number(response.headers.get('X-Total-Count')),
            } satisfies TodoResponse
          }),
        )
    },
  })

  readonly columns = [
    columnHelper.accessor('id', {
      id: 'id',
      cell: (info) => info.getValue(),
      header: () => 'Id',
      footer: (props) => props.column.id,
    }),
    columnHelper.accessor('title', {
      id: 'title',
      cell: (info) => info.getValue(),
      header: () => 'Title',
      footer: (props) => props.column.id,
    }),
    columnHelper.accessor('completed', {
      id: 'completed',
      cell: (info) => (info.getValue() ? `✅` : `❌`),
      header: () => 'Completed',
      footer: (props) => props.column.id,
    }),
  ] as Array<ColumnDef<typeof features, Todo>>

  // Keep previous value
  readonly dataWithLatest: WritableSignal<TodoResponse> = linkedSignal({
    source: () => ({
      value: this.data.value(),
      status: this.data.status(),
    }),
    computation: (source, previous) => {
      if (previous && source.status === 'loading') return previous.value
      return source.value ?? { items: [], totalCount: 0 }
    },
  })

  readonly table = injectTable(() => {
    const data = this.dataWithLatest()
    return {
      debugTable: true,
      features,
      data: data.items,
      columns: this.columns,
      state: {
        pagination: this.pagination(),
        globalFilter: this.globalFilter(),
        sorting: this.sorting(),
      },
      manualFiltering: true,
      manualPagination: true,
      manualSorting: true,
      rowCount: data.totalCount,
      onPaginationChange: (updater) =>
        typeof updater === 'function'
          ? this.pagination.update(updater)
          : this.pagination.set(updater),
      onSortingChange: (updater) => {
        typeof updater === 'function'
          ? this.sorting.update(updater)
          : this.sorting.set(updater)
      },
      onGlobalFilterChange: (updater) => {
        typeof updater === 'function'
          ? this.globalFilter.update(updater)
          : this.globalFilter.set(updater)
        this.pagination.update((page) => ({
          ...page,
          pageIndex: 0,
        }))
      },
    }
  })

  onPageInputChange(event: Event): void {
    const inputElement = event.target as HTMLInputElement
    const page = inputElement.value ? Number(inputElement.value) - 1 : 0
    this.table.setPageIndex(page)
  }

  onPageSizeChange(event: any): void {
    this.table.setPageSize(Number(event.target.value))
  }
}

import { join } from 'node:path'
import {
  AngularNodeAppEngine,
  createNodeRequestHandler,
  isMainModule,
  writeResponseToNodeResponse,
} from '@angular/ssr/node'
import express from 'express'

const browserDistFolder = join(import.meta.dirname, '../browser')

const app = express()
const angularApp = new AngularNodeAppEngine()

/**
 * Example Express Rest API endpoints can be defined here.
 * Uncomment and define endpoints as necessary.
 *
 * Example:
 * ```ts
 * app.get('/api/{*splat}', (req, res) => {
 *   // Handle API request
 * });
 * ```
 */

/**
 * Serve static files from /browser
 */
app.use(
  express.static(browserDistFolder, {
    maxAge: '1y',
    index: false,
    redirect: false,
  }),
)

/**
 * Handle all other requests by rendering the Angular application.
 */
app.use((req, res, next) => {
  angularApp
    .handle(req)
    .then((response) =>
      response ? writeResponseToNodeResponse(response, res) : next(),
    )
    .catch(next)
})

/**
 * Start the server if this module is the main entry point, or it is ran via PM2.
 * The server listens on the port defined by the `PORT` environment variable, or defaults to 4000.
 */
if (isMainModule(import.meta.url) || process.env['pm_id']) {
  const port = process.env['PORT'] || 4000
  app.listen(port, (error) => {
    if (error) {
      throw error
    }

    console.log(`Node Express server listening on http://localhost:${port}`)
  })
}

/**
 * Request handler used by the Angular CLI (for dev-server and during build) or Firebase Cloud Functions.
 */
export const reqHandler = createNodeRequestHandler(app)

