              )}
            </thead>
            <tbody>
              ${table
                .getRowModel()
                .rows.slice(0, 15)
                .map(
                  (row) => html`
                    <tr>
                      ${row
                        .getAllCells()
                        .map((cell) => html`<td>${FlexRender({ cell })}</td>`)}
                    </tr>
