declare global {
  interface HTMLElementTagNameMap {
    'dynamic-filter': DynamicFilter
    'lit-table-example': LitTableExample
  }
}

import { faker } from '@faker-js/faker'

// The example never references these keys statically. It's typed here only so the
// generated data has a realistic mix of value types (string, enum, number, boolean,
// Date) for the dynamic column-building logic to detect at runtime.
export type Person = {
  firstName: string
  lastName: string
  status: 'relationship' | 'complicated' | 'single'
  age: number
  visits: number
  progress: number
  isActive: boolean
  createdAt: Date
}

const range = (len: number) => {
  const arr: Array<number> = []
  for (let i = 0; i < len; i++) {
    arr.push(i)
  }
  return arr
}

const newPerson = (): Person => {
  return {
    firstName: faker.person.firstName(),
    lastName: faker.person.lastName(),
    status: faker.helpers.shuffle<Person['status']>([
      'relationship',
      'complicated',
      'single',
    ])[0],
    age: faker.number.int(40),
    visits: faker.number.int(1000),
    progress: faker.number.int(100),
    isActive: faker.datatype.boolean(),
    createdAt: faker.date.past({ years: 5 }),
  }
}

export function makeData(count: number) {
  return range(count).map(newPerson)
}

import { customElement, state } from 'lit/decorators.js'
import { LitElement, html } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import {
  FlexRender,
  TableController,
  createColumnHelper,
  createPaginatedRowModel,
  createSortedRowModel,
  rowPaginationFeature,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_text,
  tableFeatures,
} from '@tanstack/lit-table'
import { createAtom } from '@tanstack/store'
import { makeData } from './makeData'
import type { PaginationState, SortingState } from '@tanstack/lit-table'
import type { Person } from './makeData'

// This example demonstrates managing individual slices of table state via
// external TanStack Store atoms. Each atom is a stand-alone, subscribable
// reactive cell — you can read, write, or subscribe to it from anywhere,
// which makes it convenient for sharing state across components or modules.

const features = tableFeatures({
  rowPaginationFeature,
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    text: sortFn_text,
  },
})

const columnHelper = createColumnHelper<typeof features, Person>()

const columns = columnHelper.columns([
  columnHelper.accessor('firstName', {
    header: 'First Name',
    cell: (info) => info.getValue(),
  }),
  columnHelper.accessor('lastName', {
    header: 'Last Name',
    cell: (info) => info.getValue(),
  }),
  columnHelper.accessor('age', {
    header: 'Age',
  }),
  columnHelper.accessor('visits', {
    header: 'Visits',
  }),
  columnHelper.accessor('status', {
    header: 'Status',
  }),
  columnHelper.accessor('progress', {
    header: 'Profile Progress',
  }),
])

// Create stable external atoms for the individual state slices you want to
// own. These live at module scope here, but could just as easily be created
// in a shared store module and imported by multiple components.
const sortingAtom = createAtom<SortingState>([])
const paginationAtom = createAtom<PaginationState>({
  pageIndex: 0,
  pageSize: 10,
})

@customElement('lit-table-example')
class LitTableExample extends LitElement {
  @state()
  private _data: Array<Person> = makeData(1_000)

  private tableController = new TableController<typeof features, Person>(this)

  protected render() {
    // The table creates internal base atoms for every slice, and (because we
    // pass `atoms` below) reads/writes for `sorting` and `pagination` are
    // routed through the external atoms we created instead. The
    // TableController subscribes to `table.store` for us, so any atom change
    // flowing through the derived store triggers `host.requestUpdate()`.
    const table = this.tableController.table(
      {
        features,
        columns,
        data: this._data,
        atoms: {
          sorting: sortingAtom,
          pagination: paginationAtom,
        },
        debugTable: true,
      },
      (state) => ({
        sorting: state.sorting,
        pagination: state.pagination,
      }),
    )

    const pagination = paginationAtom.get()
    const sorting = sortingAtom.get()

    return html`
      <div class="demo-root">
        <div>
          <button
            @click=${() => {
              this._data = makeData(1_000)
            }}
          >
            Regenerate Data
          </button>
          <button
            @click=${() => {
              this._data = makeData(1_000_000)
            }}
          >
            Stress Test (1M rows)
          </button>
        </div>
        <table>
          <thead>
            ${repeat(
              table.getHeaderGroups(),
              (headerGroup) => headerGroup.id,
              (headerGroup) => html`
                <tr>
                  ${repeat(
                    headerGroup.headers,
                    (header) => header.id,
                    (header) => html`
                      <th colspan="${header.colSpan}">
                        ${
                          header.isPlaceholder
                            ? null
                            : html`<div
                                class="${
                                  header.column.getCanSort()
                                    ? 'sortable-header'
                                    : ''
                                }"
                                @click="${header.column.getToggleSortingHandler()}"
                              >
                                ${FlexRender({ header })}
                                ${
                                  {
                                    asc: ' 🔼',
                                    desc: ' 🔽',
                                  }[header.column.getIsSorted() as string] ??
                                  null
                                }
                              </div>`
                        }
                      </th>
                    `,
                  )}
                </tr>
              `,
            )}
          </thead>
          <tbody>
            ${repeat(
              table.getRowModel().rows,
              (row) => row.id,
              (row) => html`
                <tr>
                  ${repeat(
                    row.getAllCells(),
                    (cell) => cell.id,
