@customElement('lit-table-example')
class LitTableExample extends LitElement {
  private tableController = new TableController<typeof features, Person>(this)

  @state()
  private _data: Array<Person> = makeData(10)

  @state()
  private columnResizeMode: ColumnResizeMode = 'onChange'

  @state()
  private columnResizeDirection: ColumnResizeDirection = 'ltr'

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns,
        data: this._data,
        columnResizeMode: this.columnResizeMode,
        columnResizeDirection: this.columnResizeDirection,
        // initialState: { columnSizing: { firstName: 200 } }, // set column sizes on first render
        // atoms: { columnResizing: columnResizingAtom }, // preferred: own transient resize state with an external atom
        // state: { columnResizing }, // classic controlled state; pair with onColumnResizingChange
        // onColumnResizingChange: setColumnResizing,
        // enableColumnResizing: false, // disable resizing for every column; default true
        debugTable: true,
        debugHeaders: true,
        debugColumns: true,
      },
      (state) => ({
        columnSizing: state.columnSizing,
        columnResizing: state.columnResizing,
      }),
    )

    const resizerTransform = (
      header: ReturnType<
        typeof table.getHeaderGroups
      >[number]['headers'][number],
    ) => {
      if (this.columnResizeMode === 'onEnd' && header.column.getIsResizing()) {
        const delta = table.state.columnResizing.deltaOffset ?? 0
        const dir = this.columnResizeDirection === 'rtl' ? -1 : 1
        return `translateX(${dir * delta}px)`
      }
      return ''
    }

    return html`
      <div class="demo-root">
        <div>
          <button
            @click=${() => {
              this._data = makeData(10)
            }}
          >
            Regenerate Data
          </button>
