  await expect(table.locator('thead tr')).toHaveCount(3)

  await expect(headerRow(table, 0)).toHaveText(['Name', 'Info'])
  // Row two is mostly placeholders for the columns that have no middle group.
  await expect(headerRow(table, 1)).toHaveText(['', '', '', 'More Info'])
  await expect(headerRow(table, 2)).toHaveText(LEAF_HEADERS)

  expect(errors).toEqual([])
})

test('spans each group across the columns beneath it', async ({ page }) => {
  const errors = await openExample(page)
  const table = placeholderTable(page)

  // `Hello` covers two leaves, `Info` covers the other four.
  expect(await readSpans(headerRow(table, 0), 'colspan')).toEqual([2, 4])
  // `More Info` covers the last three of `Info`'s four leaves.
  expect(await readSpans(headerRow(table, 1), 'colspan')).toEqual([1, 1, 1, 3])
  expect(await readSpans(headerRow(table, 2), 'colspan')).toEqual([
    1, 1, 1, 1, 1, 1,
  ])

  // Every header row must cover the same total width as the body rows.
  for (const row of [0, 1, 2]) {
    const spans = await readSpans(headerRow(table, row), 'colspan')
    expect(spans.reduce((total, span) => total + span, 0)).toBe(
      LEAF_HEADERS.length,
    )
  }

  expect(errors).toEqual([])
})

test('mirrors the header groups in the footer', async ({ page }) => {
  const errors = await openExample(page)
  const table = placeholderTable(page)

  // Footer groups are the header groups reversed, so leaves come first.
  await expect(table.locator('tfoot tr')).toHaveCount(3)
  await expect(footerRow(table, 0)).toHaveText(LEAF_FOOTERS)

  // Both groups declare a footer, and each still spans its own
  // columns, which is what keeps the footer aligned with the body.
  await expect(footerRow(table, 2)).toHaveText(['Name', 'Info'])
  expect(await readSpans(footerRow(table, 2), 'colspan')).toEqual([2, 4])

  expect(errors).toEqual([])
})

test('spans shallow leaf headers across rows in the second table', async ({
  page,
}) => {
  const errors = await openExample(page)
  const table = rowSpanTable(page)

  await expect(table.locator('thead tr')).toHaveCount(3)

  // Placeholder headers are skipped, so each row only renders real headers.
  await expect(headerRow(table, 0)).toHaveText([
    'Full Name',
    'Info',
    'Profile Progress',
  ])
  await expect(headerRow(table, 1)).toHaveText(['Age', 'More Info'])
  await expect(headerRow(table, 2)).toHaveText(['Visits', 'Status'])

  // Top-level leaves span all three rows, `Age` spans the bottom two.
  expect(await readSpans(headerRow(table, 0), 'rowspan')).toEqual([3, 1, 3])
  expect(await readSpans(headerRow(table, 1), 'rowspan')).toEqual([2, 1])
  expect(await readSpans(headerRow(table, 2), 'rowspan')).toEqual([1, 1])

  expect(await readSpans(headerRow(table, 0), 'colspan')).toEqual([1, 3, 1])
  expect(await readSpans(headerRow(table, 1), 'colspan')).toEqual([1, 2])

  expect(errors).toEqual([])
})

import { customElement, state } from 'lit/decorators.js'
import { LitElement, html } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import { styleMap } from 'lit/directives/style-map.js'
import { faker } from '@faker-js/faker'
import {
  FlexRender,
  TableController,
  aggregationFn_mean,
  aggregationFn_median,
  aggregationFn_sum,
  createColumnHelper,
  createExpandedRowModel,
  createFacetedMinMaxValues,
  createFacetedRowModel,
  createFacetedUniqueValues,
  createFilteredRowModel,
  createGroupedRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  filterFn_inNumberRange,
  filterFn_includesString,
  metaHelper,
  sortFn_alphanumeric,
  sortFn_text,
  stockFeatures,
  tableFeatures,
} from '@tanstack/lit-table'
import { compareItems, rankItem } from '@tanstack/match-sorter-utils'
import { makeData } from './makeData'
import type { RankingInfo } from '@tanstack/match-sorter-utils'
import type { Person } from './makeData'
import type {
  Cell,
  Column,
  ColumnDef,
  FilterFn,
  Header,
  LitTable,
  Row,
  SortFn,
  TableFeatures,
} from '@tanstack/lit-table'

interface FuzzyFilterMeta {
  itemRank?: RankingInfo
}

type FuzzyFeatures = TableFeatures & { filterMeta: FuzzyFilterMeta }

interface MyColumnMeta {
  filterVariant?: 'text' | 'range' | 'select'
}

const fuzzyFilter: FilterFn<FuzzyFeatures, any> = (
  row,
  columnId,
  value,
  addMeta,
) => {
  const itemRank = rankItem(row.getValue(columnId), value)
  addMeta?.({ itemRank })
  return itemRank.passed
}

const fuzzySort: SortFn<FuzzyFeatures, any> = (rowA, rowB, columnId) => {
  let dir = 0
  if (rowA.columnFiltersMeta[columnId]) {
    dir = compareItems(
      rowA.columnFiltersMeta[columnId].itemRank!,
      rowB.columnFiltersMeta[columnId].itemRank!,
    )
  }
  return dir === 0 ? sortFn_alphanumeric(rowA, rowB, columnId) : dir
}

const features = tableFeatures({
  ...stockFeatures,
  columnMeta: metaHelper<MyColumnMeta>(),
  filterMeta: metaHelper<FuzzyFilterMeta>(),
  expandedRowModel: createExpandedRowModel(),
  filteredRowModel: createFilteredRowModel(),
  facetedRowModel: createFacetedRowModel(),
  facetedMinMaxValues: createFacetedMinMaxValues(),
  facetedUniqueValues: createFacetedUniqueValues(),
  groupedRowModel: createGroupedRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  sortedRowModel: createSortedRowModel(),
  filterFns: {
    includesString: filterFn_includesString,
    inNumberRange: filterFn_inNumberRange,
    fuzzy: fuzzyFilter,
  },
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    text: sortFn_text,
    fuzzy: fuzzySort,
  },
  aggregationFns: {
    mean: aggregationFn_mean,
    median: aggregationFn_median,
    sum: aggregationFn_sum,
  },
})

const sortStatusFn: SortFn<typeof features, Person> = (rowA, rowB) => {
  const statusOrder = ['single', 'complicated', 'relationship']
  return (
    statusOrder.indexOf(rowA.original.status) -
    statusOrder.indexOf(rowB.original.status)
  )
}

const columnHelper = createColumnHelper<typeof features, Person>()

const columns: Array<ColumnDef<typeof features, Person>> = columnHelper.columns(
  [
    columnHelper.display({
      id: 'select',
      size: 80,
      minSize: 80,
      maxSize: 80,
      enableSorting: false,
      enableGrouping: false,
      enableHiding: false,
      enableResizing: false,
      header: '',
      cell: '',
    }),
    columnHelper.accessor('firstName', {
      id: 'firstName',
      size: 200,
      header: 'First Name',
      filterFn: 'fuzzy',
      sortFn: 'fuzzy',
      meta: { filterVariant: 'text' },
      getGroupingValue: (row) => `${row.firstName} ${row.lastName}`,
    }),
    columnHelper.accessor((row) => row.lastName, {
      id: 'lastName',
      size: 180,
      header: 'Last Name',
      meta: { filterVariant: 'text' },
    }),
    columnHelper.accessor('age', {
      id: 'age',
      size: 200,
      header: 'Age',
      meta: { filterVariant: 'range' },
      aggregationFn: 'median',
      aggregatedCell: ({ getValue }) =>
        Math.round(getValue<number>() * 100) / 100,
    }),
    columnHelper.accessor('visits', {
      id: 'visits',
      size: 200,
      header: 'Visits',
      meta: { filterVariant: 'range' },
      aggregationFn: 'sum',
      aggregatedCell: ({ getValue }) => getValue<number>().toLocaleString(),
    }),
    columnHelper.accessor('status', {
      id: 'status',
      size: 200,
      header: 'Status',
      sortFn: sortStatusFn,
      meta: { filterVariant: 'select' },
    }),
    columnHelper.accessor('progress', {
      id: 'progress',
      size: 200,
      header: 'Profile Progress',
      meta: { filterVariant: 'range' },
      aggregationFn: 'mean',
      cell: ({ getValue }) => `${Math.round(getValue<number>() * 100) / 100}%`,
      aggregatedCell: ({ getValue }) =>
        `${Math.round(getValue<number>() * 100) / 100}%`,
    }),
  ],
)

@customElement('lit-table-example')
class LitTableExample extends LitElement {
  @state()
  private _data: Array<Person> = makeData(1_000)

  private tableController = new TableController<typeof features, Person>(this)

  private debounceTimers = new Map<string, ReturnType<typeof setTimeout>>()

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns,
        data: this._data,
        getSubRows: (row) => row.subRows,
        globalFilterFn: 'fuzzy',
        columnResizeMode: 'onChange',
        defaultColumn: { minSize: 200, maxSize: 800 },
        initialState: {
          columnOrder: columns.map((c) => c.id!),
          columnPinning: { start: ['select'], end: [] },
          pagination: { pageIndex: 0, pageSize: 20 },
        },
        keepPinnedRows: true,
        debugTable: true,
      },
      (state) => state, // default selector
    )

    return html`
      <div class="demo-root">
        <h1>Kitchen Sink - All Features</h1>
        <div class="toolbar">
          <div class="toolbar-row">
            <input
              class="global-filter-input"
              placeholder="Fuzzy search all columns..."
              .value=${String(table.state.globalFilter ?? '')}
              @input=${(event: InputEvent) =>
                this.debounceSet('global', () =>
                  table.setGlobalFilter(
                    (event.target as HTMLInputElement).value,
                  ),
                )}
            />
          </div>
          <div class="toolbar-row">
            <button
              class="demo-button demo-button-sm"
              @click=${() => (this._data = makeData(1_000))}
            >
              Flat 1k
            </button>
            <button
              class="demo-button demo-button-sm"
              @click=${() => (this._data = makeData(100, 5, 3))}
            >
              Nested 100x5x3
            </button>
            <button
              class="demo-button demo-button-sm"
              @click=${() => (this._data = makeData(10_000))}
            >
              Stress 10k (flat)
            </button>
            <button
              class="demo-button demo-button-sm"
              @click=${() => (this._data = makeData(100_000))}
            >
              Stress 100k (flat)
            </button>
            <button
              class="demo-button demo-button-sm"
              @click=${() => table.reset()}
            >
              Reset Table
            </button>
            <button
              class="demo-button demo-button-sm"
              @click=${() => this.shuffleColumns(table)}
            >
              Shuffle Columns
            </button>
            <span class="nowrap">
              ${table.getSelectedRowModel().flatRows.length.toLocaleString()} of
              ${table.getCoreRowModel().flatRows.length.toLocaleString()}
              selected
            </span>
          </div>
          <details class="column-toggle-panel">
            <summary class="column-toggle-panel-header">
              Column visibility
            </summary>
            <div class="column-toggle-row">
              <label>
                <input
                  type="checkbox"
                  ?checked=${table.getIsAllColumnsVisible()}
                  @change=${table.getToggleAllColumnsVisibilityHandler()}
                />
                Toggle All
              </label>
            </div>
            ${table.getAllLeafColumns().map(
              (column) => html`
                <div class="column-toggle-row">
                  <label>
                    <input
                      type="checkbox"
                      ?checked=${column.getIsVisible()}
                      ?disabled=${!column.getCanHide()}
                      @change=${column.getToggleVisibilityHandler()}
                    />
                    ${column.id}
                  </label>
                </div>
              `,
            )}
          </details>
        </div>

  private renderCell(
    table: LitTable<typeof features, Person>,
    cell: Cell<typeof features, Person, unknown>,
  ) {
    return html`
      <td
        style=${styleMap(this.cellStyle(cell))}
        class=${this.cellClass(table, cell) ?? ''}
      >
        ${
          cell.column.id === 'select'
            ? html`<div class="column-toggle-row">
                <input
                  type="checkbox"
                  ?checked=${cell.row.getIsSelected()}
                  ?disabled=${!cell.row.getCanSelect()}
                  .indeterminate=${cell.row.getIsSomeSelected()}
                  @click=${cell.row.getToggleSelectedHandler()}
                />
                <button
                  class="pin-button"
                  @click=${() =>
                    cell.row.pin(
                      cell.row.getIsPinned() === 'top' ? false : 'top',
                    )}
                >
                  ${cell.row.getIsPinned() === 'top' ? 'Pinned' : 'Pin'}
                </button>
              </div>`
            : cell.column.id === 'firstName'
              ? html`<div style="padding-left: ${cell.row.depth * 1.5}rem">
                  ${
                    cell.row.getCanExpand()
                      ? html`<button
                          @click=${cell.row.getToggleExpandedHandler()}
                          style="cursor: pointer; margin-right: 0.25rem"
                        >
                          ${cell.row.getIsExpanded() ? 'v' : '>'}
                        </button>`
                      : html`<span style="margin-right: 0.25rem">-</span>`
                  }
                  ${FlexRender({ cell })}
                </div>`
              : cell.getIsGrouped()
                ? html`<button
                    @click=${cell.row.getToggleExpandedHandler()}
                    style="cursor: ${
                      cell.row.getCanExpand() ? 'pointer' : 'normal'
                    }"
                  >
                    ${cell.row.getIsExpanded() ? 'v' : '>'}
                    ${FlexRender({ cell })}
                    (${cell.row.subRows.length.toLocaleString()})
                  </button>`
                : FlexRender({ cell })
        }
      </td>
    `
  }

  private debounceSet(key: string, setValue: () => void) {
    clearTimeout(this.debounceTimers.get(key))
    this.debounceTimers.set(
      key,
      setTimeout(() => {
        setValue()
        this.debounceTimers.delete(key)
      }, 300),
    )
  }

  private shuffleColumns(table: LitTable<typeof features, Person>) {
    table.setColumnOrder(
      faker.helpers.shuffle(table.getAllLeafColumns().map((d) => d.id)),
    )
  }

  private getCommonPinningStyle(column: Column<typeof features, Person>) {
    const isPinned = column.getIsPinned()
    const isLastLeftPinnedColumn =
      isPinned === 'start' && column.getIsLastColumn('start')
    const isFirstRightPinnedColumn =
      isPinned === 'end' && column.getIsFirstColumn('end')

    return {
      boxShadow: isLastLeftPinnedColumn
        ? '-4px 0 4px -4px gray inset'
        : isFirstRightPinnedColumn
          ? '4px 0 4px -4px gray inset'
          : undefined,
      insetInlineStart:
        isPinned === 'start' ? `${column.getStart('start')}px` : undefined,
      insetInlineEnd:
        isPinned === 'end' ? `${column.getAfter('end')}px` : undefined,
      opacity: isPinned ? '0.97' : '1',
      position: isPinned ? 'sticky' : 'relative',
      zIndex: isPinned ? '1' : '0',
    }
  }

  private headerStyle(header: Header<typeof features, Person, unknown>) {
    return {
      ...this.getCommonPinningStyle(header.column),
      whiteSpace: 'nowrap',
      width: `calc(var(--header-${header.id}-size) * 1px)`,
    }
  }

  private cellStyle(cell: Cell<typeof features, Person, unknown>) {
    return {
      ...this.getCommonPinningStyle(cell.column),
      width: `calc(var(--col-${cell.column.id}-size) * 1px)`,
    }
  }

  private pinnedRowStyle(
    table: LitTable<typeof features, Person>,
    row: Row<typeof features, Person>,
  ) {
    const bottomRows = table.getBottomRows()
    return {
      position: 'sticky',
      top:
        row.getIsPinned() === 'top'
          ? `${row.getPinnedIndex() * 32 + 48}px`
          : undefined,
      bottom:
        row.getIsPinned() === 'bottom'
          ? `${(bottomRows.length - 1 - row.getPinnedIndex()) * 32}px`
          : undefined,
      zIndex: '1',
    }
  }

  private cellClass(
    table: LitTable<typeof features, Person>,
    cell: Cell<typeof features, Person, unknown>,
  ) {
    const groupingActive = table.state.grouping.length > 0
    const hasAggregation = !!cell.column.columnDef.aggregationFn
    return !groupingActive
      ? undefined
      : cell.getIsGrouped()
        ? 'cell-grouped'
        : hasAggregation && cell.getIsAggregated()
          ? 'cell-aggregated'
          : cell.getIsPlaceholder()
            ? 'cell-placeholder'
            : undefined
  }

  private tableStyle(table: LitTable<typeof features, Person>) {
    const styles = [`width: ${table.getTotalSize()}px`]
    for (const header of table.getFlatHeaders()) {
      styles.push(`--header-${header.id}-size: ${header.getSize()}`)
      styles.push(`--col-${header.column.id}-size: ${header.column.getSize()}`)
    }
    return styles.join('; ')
  }

