@customElement('lit-table-example')
class LitTableExample extends LitElement {
  private tableController = new TableController<typeof features, Person>(this)

  private tableContainerRef: Ref = createRef()

  private rowVirtualizerController!: VirtualizerController<Element, Element>

  @state()
  private _data: Array<Person> = []

  @state()
  private _isFetching = false

  @state()
  private _totalRowCount = 0

  @state()
  private _sorting: SortingState = []

  connectedCallback() {
    super.connectedCallback()
    // Fetch initial data
    this._fetchMoreData()
  }

  private async _fetchMoreData() {
    if (this._isFetching) return

    this._isFetching = true

    try {
      const response = await fetchData(
        this._data.length,
        fetchSize,
        this._sorting,
      )
      this._data = [...this._data, ...response.data]
      this._totalRowCount = response.meta.totalRowCount
    } finally {
      this._isFetching = false
    }
  }

  private async _refetchData() {
    this._isFetching = true
    this._data = []

    try {
      const response = await fetchData(0, fetchSize, this._sorting)
      this._data = response.data
      this._totalRowCount = response.meta.totalRowCount
    } finally {
      this._isFetching = false
    }
  }

  private _handleScroll(e: Event) {
    const target = e.currentTarget as HTMLDivElement
    const { scrollHeight, scrollTop, clientHeight } = target
    if (
      scrollHeight - scrollTop - clientHeight < 500 &&
      !this._isFetching &&
      this._data.length < this._totalRowCount
    ) {
      this._fetchMoreData()
    }
  }

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns,
        data: this._data,
        state: {
          sorting: this._sorting,
        },
        manualSorting: true,
        onSortingChange: (updater) => {
          const newSorting =
            typeof updater === 'function' ? updater(this._sorting) : updater
          this._sorting = newSorting
          // Reset data and refetch when sorting changes
          this._refetchData()
          // Scroll back to top
          if (this.tableContainerRef.value) {
            this.tableContainerRef.value.scrollTop = 0
          }
        },
      },
      () => ({}),
    )

    const { rows } = table.getRowModel()

    if (!this.rowVirtualizerController) {
      this.rowVirtualizerController = new VirtualizerController(this, {
        count: rows.length,
        estimateSize: () => 33,
        getScrollElement: () => this.tableContainerRef.value!,
        overscan: 5,
      })
    }

    const virtualizer = this.rowVirtualizerController.getVirtualizer()

    // Update count when rows change
    virtualizer.setOptions({
      ...virtualizer.options,
      count: rows.length,
    })

    const virtualRows = virtualizer.getVirtualItems()

    return html`
      <div class="app">
        (${this._data.length.toLocaleString()} of
        ${this._totalRowCount.toLocaleString()} rows fetched)
        <div
          class="container"
          ${ref(this.tableContainerRef)}
          @scroll="${this._handleScroll}"
          style="${styleMap({
            overflow: 'auto',
            position: 'relative',
            height: '600px',
          })}"
        >
          <table style="display: grid">
            <thead
              style="${styleMap({
                display: 'grid',
                position: 'sticky',
                top: '0',
                zIndex: '1',
              })}"
            >
              ${repeat(
                table.getHeaderGroups(),
                (headerGroup) => headerGroup.id,
                (headerGroup) => html`
                  <tr style="${styleMap({ display: 'flex', width: '100%' })}">
                    ${repeat(
                      headerGroup.headers,
                      (header) => header.id,
                      (header) => html`
                        <th
                          style="${styleMap({
                            display: 'flex',
                            width: `${header.getSize()}px`,
                          })}"
                          @click="${header.column.getToggleSortingHandler()}"
                        >
                          ${FlexRender({ header })}
                          ${
                            {
                              asc: ' 🔼',
                              desc: ' 🔽',
                            }[header.column.getIsSorted() as string] ?? null
                          }
                        </th>
                      `,
                    )}
                  </tr>
                `,
              )}
            </thead>
            <tbody
              style="${styleMap({
                display: 'grid',
                height: `${virtualizer.getTotalSize()}px`,
                position: 'relative',
              })}"
            >
              ${repeat(
                virtualRows,
                (item) => item.key,
                (virtualRow) => {
                  const row = rows[virtualRow.index]
                  return html`
                    <tr
                      data-index="${virtualRow.index}"
                      style="${styleMap({
                        display: 'flex',
                        position: 'absolute',
                        transform: `translateY(${virtualRow.start}px)`,
                        width: '100%',
                      })}"
                      ${ref((node) => virtualizer.measureElement(node ?? null))}
                    >
                      ${repeat(
                        row.getAllCells(),
                        (cell) => cell.id,
                        (cell) => html`
                          <td
                            style="${styleMap({
                              display: 'flex',
                              width: `${cell.column.getSize()}px`,
                            })}"
                          >
                            ${FlexRender({ cell })}
                          </td>
                        `,
                      )}
                    </tr>
                  `
                },
              )}
            </tbody>
          </table>
        </div>
        ${this._isFetching ? html`<div>Fetching More...</div>` : null}
      </div>

      <style>
        html {
          font-family: sans-serif;
          font-size: 14px;
        }

        table {
          font-family: arial, sans-serif;
          table-layout: fixed;
        }

        thead {
          background: lightgray;
        }

        tr {
          border-bottom: 1px solid lightgray;
        }

        th {
          border-bottom: 1px solid lightgray;
          border-right: 1px solid lightgray;
          padding: 2px 4px;
          text-align: left;
          cursor: pointer;
        }

        td {
          padding: 6px;
        }

        .container {
          border: 1px solid lightgray;
          margin: 1rem auto;
        }

        .app {
          margin: 1rem auto;
          text-align: center;
        }

import { faker } from '@faker-js/faker'
import type { SortingState } from '@tanstack/lit-table'

export type Person = {
  id: number
  firstName: string
  lastName: string
  age: number
  visits: number
  progress: number
  status: 'relationship' | 'complicated' | 'single'
  createdAt: Date
}

export type PersonApiResponse = {
  data: Array<Person>
  meta: {
    totalRowCount: number
  }
}

const range = (len: number) => {
  const arr: Array<number> = []
  for (let i = 0; i < len; i++) {
    arr.push(i)
  }
  return arr
}

const newPerson = (index: number): Person => {
  return {
    id: index + 1,
    firstName: faker.person.firstName(),
    lastName: faker.person.lastName(),
    age: faker.number.int(40),
    visits: faker.number.int(1000),
    progress: faker.number.int(100),
    createdAt: faker.date.anytime(),
    status: faker.helpers.shuffle<Person['status']>([
      'relationship',
      'complicated',
      'single',
    ])[0],
  }
}

export function makeData(...lens: Array<number>) {
  const makeDataLevel = (depth = 0): Array<Person> => {
    const len = lens[depth]
    return range(len).map((d): Person => {
      return {
        ...newPerson(d),
      }
    })
  }

  return makeDataLevel()
}

const data = makeData(1000)

// simulates a backend api
export const fetchData = async (
  start: number,
  size: number,
  sorting: SortingState,
): Promise<PersonApiResponse> => {
  const dbData = [...data]
  if (sorting.length) {
    const sort = sorting[0]
    const { id, desc } = sort as { id: keyof Person; desc: boolean }
    dbData.sort((a, b) => {
      if (desc) {
        return a[id] < b[id] ? 1 : -1
      }
      return a[id] > b[id] ? 1 : -1
    })
  }

  // simulate a backend api
  await new Promise((resolve) => setTimeout(resolve, 200))

  return {
    data: dbData.slice(start, start + size),
    meta: {
      totalRowCount: dbData.length,
    },
  }
}

