test('reorders rows to match the sorted column', async ({ page }) => {
  const errors = await openExample(page)
  const toggle = sortToggle(page, 'age')
  const unsorted = await readNumericColumn(page, 'age')

  await toggle.click()
  await expect(toggle).toContainText('🔽')

  const descending = await readNumericColumn(page, 'age')
  expect(descending).toEqual([...descending].sort((a, b) => b - a))
  // The top row now holds the maximum across all 1,000 rows, which is at least
  // the maximum of the ten that happened to be visible before sorting.
  expect(descending[0]).toBeGreaterThanOrEqual(Math.max(...unsorted))

  await toggle.click()
  await expect(toggle).toContainText('🔼')

  const ascending = await readNumericColumn(page, 'age')
  expect(ascending).toEqual([...ascending].sort((a, b) => a - b))
  expect(ascending[0]).toBeLessThanOrEqual(Math.min(...unsorted))

  expect(errors).toEqual([])
})

test('inverts the rendered order on the Rank column', async ({ page }) => {
  const errors = await openExample(page)
  const toggle = sortToggle(page, 'rank')
  const unsorted = await readNumericColumn(page, 'rank')

  await toggle.click()
  await expectSorting(page, [{ id: 'rank', desc: true }])
  await expect(toggle).toContainText('🔽')

  // `invertSorting: true` flips the comparison after the descending flip, so a
  // column marked descending renders ascending values. Golf scores, not typos.
  const ranks = await readNumericColumn(page, 'rank')
  expect(ranks).toEqual([...ranks].sort((a, b) => a - b))
  expect(ranks[0]).toBeLessThanOrEqual(Math.min(...unsorted))

  expect(errors).toEqual([])
})

test('keeps undefined values last in both sort directions', async ({
  page,
}) => {
  const errors = await openExample(page)
  const toggle = sortToggle(page, 'lastName')

  // Roughly a tenth of the 1,000 rows have an undefined last name. The default
  // `sortUndefined` would surface them at one end; `'last'` pins them to the
  // bottom regardless of direction, so neither direction shows a blank cell.
  await toggle.click()
  await expect(toggle).toContainText('🔼')

  const ascending = await readColumn(page, 'lastName')
  expect(ascending).toHaveLength(10)
  expect(ascending.filter((name) => name === '')).toEqual([])

  await toggle.click()
  await expect(toggle).toContainText('🔽')

  const descending = await readColumn(page, 'lastName')
  expect(descending).toHaveLength(10)
  expect(descending.filter((name) => name === '')).toEqual([])

  expect(errors).toEqual([])
})

test('sorts by a custom sort function', async ({ page }) => {
  const errors = await openExample(page)
  const toggle = sortToggle(page, 'status')

  // Ascending puts `single` first. An alphanumeric fallback would put
  // `complicated` there instead, so this fails if `sortStatusFn` is dropped.
  await toggle.click()
  await expectSorting(page, [{ id: 'status', desc: false }])
  await expect(toggle).toContainText('🔼')

  const ascending = await readColumn(page, 'status')
  expect([...new Set(ascending)]).toEqual([STATUS_ORDER[0]])

  await toggle.click()
  await expect(toggle).toContainText('🔽')

  const descending = await readColumn(page, 'status')
  expect([...new Set(descending)]).toEqual([STATUS_ORDER[2]])

  expect(errors).toEqual([])
})

test('multi-sorts with Shift-click', async ({ page }) => {
  const errors = await openExample(page)

  await sortToggle(page, 'status').click()
  await expectSorting(page, [{ id: 'status', desc: false }])

  // Shift appends a column rather than replacing the sort.
  await sortToggle(page, 'age').click({ modifiers: ['Shift'] })
  await expectSorting(page, [
    { id: 'status', desc: false },
    { id: 'age', desc: true },
  ])
  await expect(sortToggle(page, 'status')).toContainText('🔼')
  await expect(sortToggle(page, 'age')).toContainText('🔽')

  // A shifted column runs its own asc/desc/remove cycle.
  await sortToggle(page, 'age').click({ modifiers: ['Shift'] })
  await expectSorting(page, [
    { id: 'status', desc: false },
    { id: 'age', desc: false },
  ])

  await sortToggle(page, 'age').click({ modifiers: ['Shift'] })
  await expectSorting(page, [{ id: 'status', desc: false }])

  // An unshifted click on another column replaces the whole sort.
  await sortToggle(page, 'firstName').click()
  await expectSorting(page, [{ id: 'firstName', desc: false }])

  expect(errors).toEqual([])
})

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

const TOTAL_ROWS = 10

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.goto(server.url)

  return errors
}

function bodyRows(page: Page) {
  return page.locator('tbody tr')
}

/** Every data row carries an expander in its first cell. */
function rowExpander(page: Page, index: number) {
  return bodyRows(page).nth(index).getByRole('button')
}

/** The sub component renders the row's own data as JSON inside a `<pre>`. */
function subComponents(page: Page) {
  return page.locator('tbody pre')
}

async function readSubComponentJson(page: Page, index: number) {
  const text = await subComponents(page).nth(index).textContent()
  return JSON.parse(text ?? '{}') as Record<string, unknown>
}

async function getFirstBodyRowText(page: Page) {
  const text = await bodyRows(page).first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)
  // Nothing is expanded, so no sub component rows exist yet.
  await expect(subComponents(page)).toHaveCount(0)
  await expect(rowExpander(page, 0)).toHaveText('👉')

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(bodyRows(page).first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('expands a row to reveal its sub component', async ({ page }) => {
  const errors = await openExample(page)

  await rowExpander(page, 0).click()

  await expect(rowExpander(page, 0)).toHaveText('👇')
  await expect(subComponents(page)).toHaveCount(1)
  // The sub component adds a full width row directly beneath its parent.
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS + 1)
  await expect(bodyRows(page).nth(1).locator('td')).toHaveCount(1)

  await rowExpander(page, 0).click()

  await expect(rowExpander(page, 0)).toHaveText('👉')
  await expect(subComponents(page)).toHaveCount(0)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('renders the expanded row own data in the sub component', async ({
  page,
}) => {
  const errors = await openExample(page)

  // Read a value straight out of the row before opening it, so the sub
  // component can be checked against its own parent rather than any row.
  const ageCell = await bodyRows(page)
    .first()
    .locator('td')
    .nth(3)
    .textContent()

  await rowExpander(page, 0).click()
  await expect(subComponents(page)).toHaveCount(1)

  const original = await readSubComponentJson(page, 0)
  expect(original['age']).toBe(Number(ageCell?.trim()))
  expect(original).toHaveProperty('firstName')
  expect(original).toHaveProperty('status')

  expect(errors).toEqual([])
})

test('keeps several sub components open at once', async ({ page }) => {
  const errors = await openExample(page)

  await rowExpander(page, 0).click()
  await expect(subComponents(page)).toHaveCount(1)

  // Row 1 is now the first sub component row, so the next data row is row 2.
  await rowExpander(page, 2).click()

  await expect(subComponents(page)).toHaveCount(2)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS + 2)
  await expect(rowExpander(page, 0)).toHaveText('👇')
  await expect(rowExpander(page, 2)).toHaveText('👇')

  // Collapsing one leaves the other open.
  await rowExpander(page, 0).click()

  await expect(subComponents(page)).toHaveCount(1)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS + 1)

  expect(errors).toEqual([])
})

import { render } from 'preact'
import { useMemo, useState } from 'preact/hooks'
import './index.css'
import {
  aggregationFn_count,
  aggregationFn_extent,
  aggregationFn_mean,
  aggregationFn_sum,
  columnFilteringFeature,
  createColumnHelper,
  createFilteredRowModel,
  createPaginatedRowModel,
  filterFn_includesString,
  metaHelper,
  rowAggregationFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  tableFeatures,
  useTable,
} from '@tanstack/preact-table'
import { makeData } from './makeData'
import type { Table } from '@tanstack/preact-table'
import type { Sale } from './makeData'

type RowSource = 'all' | 'custom' | 'filtered' | 'page' | 'selected'
type AggregationTableMeta = { rowSource: RowSource }

const features = tableFeatures({
  rowAggregationFeature,
  columnFilteringFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  filteredRowModel: createFilteredRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  filterFns: { includesString: filterFn_includesString },
  aggregationFns: {
    count: aggregationFn_count,
    extent: aggregationFn_extent,
    mean: aggregationFn_mean,
    sum: aggregationFn_sum,
  },
  tableMeta: metaHelper<AggregationTableMeta>(),
})

const columnHelper = createColumnHelper<typeof features, Sale>()

function getAggregationRows(table: Table<typeof features, Sale>) {
  const rowSource = table.options.meta?.rowSource
  if (rowSource === 'all') return table.getCoreRowModel().rows
  if (rowSource === 'page') return table.getRowModel().rows
  if (rowSource === 'selected') return table.getFilteredSelectedRowModel().rows
  if (rowSource === 'custom') return table.getCoreRowModel().rows.slice(0, 3)
  return undefined
}

function formatValue(value: unknown): string {
  if (Array.isArray(value)) return value.map(formatValue).join(' – ')
  if (value && typeof value === 'object') {
    return Object.entries(value)
      .map(([key, entry]) => `${key}: ${formatValue(entry)}`)
      .join(', ')
  }
  if (typeof value === 'number')
    return value.toLocaleString(undefined, { maximumFractionDigits: 2 })
  return String(value ?? '—')
}

function App() {
  const [data, setData] = useState(() => makeData(10_000))
  const [rowSource, setRowSource] = useState<RowSource>('filtered')
  const columns = useMemo(
    () =>
      columnHelper.columns([
        columnHelper.display({
          id: 'select',
          header: ({ table }) => (
            <input
              type="checkbox"
              checked={table.getIsAllPageRowsSelected()}
              onChange={table.getToggleAllPageRowsSelectedHandler()}
            />
          ),
          cell: ({ row }) => (
            <input
              type="checkbox"
              checked={row.getIsSelected()}
              onChange={row.getToggleSelectedHandler()}
            />
          ),
        }),
        columnHelper.accessor('category', {
          header: 'Category',
          filterFn: 'includesString',
        }),
        columnHelper.accessor('item', {
          header: 'Item',
          footer: ({ table }) => `${table.options.meta?.rowSource} total`,
        }),
        columnHelper.accessor('amount', {
          header: 'Amount',
          aggregationFn: 'sum',
          cell: ({ getValue }) => getValue<number>().toLocaleString(),
          footer: ({ column, table }) =>
            formatValue(
              column.getAggregationValue({ rows: getAggregationRows(table) }),
            ),
        }),
        columnHelper.accessor('score', {
          header: 'Score',
          aggregationFn: [
            'count',
            'mean',
            { id: 'range', aggregationFn: 'extent' },
          ],
          footer: ({ column, table }) =>
            formatValue(
              column.getAggregationValue({ rows: getAggregationRows(table) }),
            ),
        }),
      ]),
    [],
  )

  const table = useTable(
    {
      features,
      columns,
      data,
      meta: { rowSource },
      initialState: { pagination: { pageIndex: 0, pageSize: 10 } },
      // manualAggregation: true, // supply aggregate values yourself instead of calculating them locally
      debugTable: true,
      debugColumns: true,
    },
    (state) => state, // default selector
  )

  return (
    <div className="demo-root">
      <h1>Aggregation without grouping</h1>
      <p>
        Amount uses a scalar <code>sum</code>. Score runs count, mean, and range
        together and returns a keyed object.
      </p>
      <div>
        <button onClick={() => setData(makeData(10_000))}>
          Regenerate Data
        </button>
        <button onClick={() => setData(makeData(1_000_000))}>
          Stress Test (1M rows)
        </button>
      </div>
      <div className="spacer-sm" />
      <div className="controls">
        <label>
          Category filter:{' '}
          <input
            value={
              (table.getColumn('category')?.getFilterValue() ?? '') as string
            }
            onChange={(event) =>
              table
                .getColumn('category')
                ?.setFilterValue(event.currentTarget.value)
            }
          />
        </label>
        <label>
          Total rows:{' '}
          <select
            value={rowSource}
            onChange={(event) =>
              setRowSource(event.currentTarget.value as RowSource)
            }
          >
            <option value="filtered">Filtered rows</option>
            <option value="all">All rows</option>
            <option value="page">Visible page</option>
            <option value="selected">Filtered selected rows</option>
            <option value="custom">First three core rows</option>
          </select>
        </label>
      </div>
      <div className="spacer-sm" />
      <table>
        <thead>
          {table.getHeaderGroups().map((group) => (
            <tr key={group.id}>
              {group.headers.map((header) => (
                <th key={header.id}>
                  {header.isPlaceholder ? null : (
