// A different filter UI per data type. Preact's `useTable` selector re-runs `App`
// (and therefore this component) whenever the selected state changes, so the reads
// below (getFilterValue, the faceted values) stay fresh without any extra wiring.
// No `table.Subscribe` workaround is needed here since this example's Vite config
// has no React Compiler plugin.
function Filter({
  column,
  table: _table,
}: {
  column: Column<typeof features, DynamicRow, unknown>
  table: DynamicTable
}) {
  const { dataType } = column.columnDef.meta ?? { dataType: 'string' }

  const filterValue = column.getFilterValue()

  if (dataType === 'number') {
    const [min, max] = column.getFacetedMinMaxValues() ?? []
    return (
      <div className="filter-row">
        <DebouncedInput
          type="number"
          value={(filterValue as [number, number] | undefined)?.[0] ?? ''}
          onChange={(value) =>
            column.setFilterValue((old: [number, number] | undefined) => [
              value,
              old?.[1],
            ])
          }
          placeholder={`Min${min !== undefined ? ` (${min})` : ''}`}
          className="filter-input"
        />
        <DebouncedInput
          type="number"
          value={(filterValue as [number, number] | undefined)?.[1] ?? ''}
          onChange={(value) =>
            column.setFilterValue((old: [number, number] | undefined) => [
              old?.[0],
              value,
            ])
          }
          placeholder={`Max${max !== undefined ? ` (${max})` : ''}`}
          className="filter-input"
        />
      </div>
    )
  }

  if (dataType === 'date') {
    return (
      <div className="filter-row">
        <DebouncedInput
          type="date"
          value={(filterValue as [string, string] | undefined)?.[0] ?? ''}
          onChange={(value) =>
            column.setFilterValue((old: [string, string] | undefined) => [
              String(value),
              old?.[1] ?? '',
            ])
          }
          className="filter-input"
        />
        <DebouncedInput
          type="date"
          value={(filterValue as [string, string] | undefined)?.[1] ?? ''}
          onChange={(value) =>
            column.setFilterValue((old: [string, string] | undefined) => [
              old?.[0] ?? '',
              String(value),
            ])
          }
          className="filter-input"
        />
      </div>
    )
  }

  if (dataType === 'boolean') {
    return (
      <select
        className="filter-select"
        value={(filterValue ?? '').toString()}
        onChange={(e) =>
          column.setFilterValue((e.target as HTMLSelectElement).value)
        }
      >
        <option value="">All</option>
        <option value="true">Yes</option>
        <option value="false">No</option>
      </select>
    )
  }

  // string: low-cardinality columns become a select of their faceted values,
  // everything else gets a free-text search.
  const uniqueValues = Array.from(column.getFacetedUniqueValues().keys())
    .map(String)
    .sort()
  const isEnum = uniqueValues.length > 0 && uniqueValues.length <= 10

  if (isEnum) {
    return (
      <select
        className="filter-select"
        value={(filterValue ?? '').toString()}
        onChange={(e) =>
          column.setFilterValue((e.target as HTMLSelectElement).value)
        }
      >
        <option value="">All</option>
        {uniqueValues.map((value) => (
          <option key={value} value={value}>
            {value}
          </option>
        ))}
      </select>
    )
  }

  return (
    <DebouncedInput
      type="text"
      value={(filterValue ?? '') as string}
      onChange={(value) => column.setFilterValue(value)}
      placeholder={`Search... (${column.getFacetedUniqueValues().size})`}
      className="filter-input"
    />
  )
}

// A typical debounced input preact component
function DebouncedInput({
  value: initialValue,
  onChange,
  debounce = 500,
  ...props
}: {
  value: string | number
  onChange: (value: string | number) => void
  debounce?: number
} & Record<string, any>) {
  const [value, setValue] = useState(initialValue)

  useEffect(() => {
    setValue(initialValue)
  }, [initialValue])

  const debouncedOnChange = useDebouncedCallback(onChange, { wait: debounce })

  return (
    <input
      {...props}
      value={value}
      onInput={(e) => {
        const nextValue = (e.target as HTMLInputElement).value
        setValue(nextValue)
        debouncedOnChange(nextValue)
      }}
    />
  )
}

